}

function validate(sections, maxBytes) {
  if (!Number.isSafeInteger(maxBytes) || maxBytes < 0) {
    throw invalid('maxBytes must be a nonnegative safe integer');
  }
  if (!Array.isArray(sections)) {
    throw invalid('sections must be an array');
  }

  const ids = new Set();
  const validated = [];

  for (let index = 0; index < sections.length; index += 1) {
    if (!Object.hasOwn(sections, index)) {
      throw invalid(`sections has a missing element at index ${index}`);
    }

    const section = sections[index];
    if (section === null || typeof section !== 'object' || Array.isArray(section)) {
      throw invalid(`section at index ${index} must be a non-null, non-array object`);
    }

    for (const field of ['id', 'text', 'priority', 'required']) {
      if (!Object.hasOwn(section, field)) {
        throw invalid(`section at index ${index} is missing ${field}`);
      }
    }

    const {id, text, priority, required} = section;
    if (typeof id !== 'string' || id.length === 0) {
      throw invalid(`section at index ${index} has an invalid id`);
    }
    if (ids.has(id)) {
      throw invalid(`duplicate section id ${JSON.stringify(id)}`);
    }
    if (typeof text !== 'string') {
      throw invalid(`section ${JSON.stringify(id)} has invalid text`);
    }
    if (!Number.isSafeInteger(priority) || priority < 0) {
      throw invalid(`section ${JSON.stringify(id)} has invalid priority`);
    }
    if (typeof required !== 'boolean') {
      throw invalid(`section ${JSON.stringify(id)} has invalid required`);
    }

    ids.add(id);
    const frame = `### ${JSON.stringify(id)}\n${text}\n`;
    validated.push({
      id,
      priority,
      required,
      index,
      frame,
      bytes: Buffer.byteLength(frame, 'utf8'),
    });
  }

  return validated;
}

export function packContext(sections, maxBytes) {
  const validated = validate(sections, maxBytes);
  const required = validated.filter((section) => section.required);
  const requiredBytes = required.reduce((sum, section) => sum + section.bytes, 0);

  if (requiredBytes > maxBytes) {
    throw new Error('Required sections exceed maxBytes');
  }

  const optional = validated
    .filter((section) => !section.required)
    .sort((left, right) => {
      if (left.priority !== right.priority) {
