      }
      return left.index - right.index;
    });

  const includedSections = [...required];
  const includedOptionalIndexes = new Set();
  let bytes = requiredBytes;

  for (const section of optional) {
    if (section.bytes <= maxBytes - bytes) {
      includedSections.push(section);
      includedOptionalIndexes.add(section.index);
      bytes += section.bytes;
    }
