    text: includedSections.map((section) => section.frame).join(''),
    bytes,
    included: includedSections.map((section) => section.id),
    omitted: validated
      .filter((section) => !section.required && !includedOptionalIndexes.has(section.index))
      .map((section) => section.id),
  };
}

